    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nfrom random import shuffle\n\nclass Solution:\n    def maxConsistentColumns(self, grid: List[List[int]], limit: int) -> int:\n        shuffle(grid)\n        candidates = []\n        N = len(grid)\n        M = len(grid[0])\n        for j in range(M):\n            insert_pos = len(candidates)\n            insert_value = candidates[-1][1] if candidates else 1\n            for k in range(len(candidates) - 1, -1, -1):\n                x, v = candidates[k]\n                for i in range(N):\n                    if abs(grid[i][x] - grid[i][j]) > limit:\n                        break\n                else:\n                    break\n            else:\n                # no valid target\n                candidates.insert(0, (j, 1))\n                continue\n            # find k, x, v\n            for k2 in range(len(candidates) - 1, k - 1, -1):\n                if candidates[k2][1] <= v + 1:\n                    break\n            candidates.insert(k2 + 1, (j, v + 1))\n        return candidates[-1][1]\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.maxConsistentColumns(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
