PDH06 = mk(
    "DH06",
    "\u7528\u4e09\u79cd\u4e0d\u540c\u989c\u8272\u4e3a\u7f51\u683c\u6d82\u8272",
    "LeetCode 1931",
    "hard",
    "\u52a8\u6001\u89c4\u5212",
    "\u7ed9\u4f60\u4e24\u4e2a\u6574\u6570 m \u548c n \u3002\u6784\u9020\u4e00\u4e2a m x n \u7684\u7f51\u683c\uff0c\u5176\u4e2d\u6bcf\u4e2a\u5355\u5143\u683c\u6700\u5f00\u59cb\u662f\u767d\u8272\u3002\u8bf7\u4f60\u7528 \u7ea2\u3001\u7eff\u3001\u84dd \u4e09\u79cd\u989c\u8272\u4e3a\u6bcf\u4e2a\u5355\u5143\u683c\u6d82\u8272\u3002\u6240\u6709\u5355\u5143\u683c\u90fd\u9700\u8981\u88ab\u6d82\u8272\u3002\n\n\u6d82\u8272\u65b9\u6848\u9700\u8981\u6ee1\u8db3\uff1a\u4e0d\u5b58\u5728\u76f8\u90bb\u4e24\u4e2a\u5355\u5143\u683c\u989c\u8272\u76f8\u540c\u7684\u60c5\u51b5 \u3002\u8fd4\u56de\u7f51\u683c\u6d82\u8272\u7684\u65b9\u6cd5\u6570\u3002\u56e0\u4e3a\u7b54\u6848\u53ef\u80fd\u975e\u5e38\u5927\uff0c \u8fd4\u56de \u5bf9 109 + 7 \u53d6\u4f59 \u7684\u7ed3\u679c\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1am = 1, n = 1\n\u8f93\u51fa\uff1a3\n\u89e3\u91ca\uff1a\u5982\u4e0a\u56fe\u6240\u793a\uff0c\u5b58\u5728\u4e09\u79cd\u53ef\u80fd\u7684\u6d82\u8272\u65b9\u6848\u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1am = 1, n = 2\n\u8f93\u51fa\uff1a6\n\u89e3\u91ca\uff1a\u5982\u4e0a\u56fe\u6240\u793a\uff0c\u5b58\u5728\u516d\u79cd\u53ef\u80fd\u7684\u6d82\u8272\u65b9\u6848\u3002\n```\n\n\u793a\u4f8b 3\uff1a\n\n```\n\u8f93\u5165\uff1am = 5, n = 5\n\u8f93\u51fa\uff1a580986\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1\n\n\t1",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1am\u3001n\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def colorTheGrid(self, m: int, n: int) -> int:\n        mod = 10**9 + 7\n        # \u54c8\u5e0c\u6620\u5c04 valid \u5b58\u50a8\u6240\u6709\u6ee1\u8db3\u8981\u6c42\u7684\u5bf9\u4e00\u884c\u8fdb\u884c\u6d82\u8272\u7684\u65b9\u6848\n        # \u952e\u8868\u793a mask\uff0c\u503c\u8868\u793a mask \u7684\u4e09\u8fdb\u5236\u4e32\uff08\u4ee5\u5217\u8868\u7684\u5f62\u5f0f\u5b58\u50a8\uff09\n        valid = dict()\n        \n        # \u5728 [0, 3^m) \u8303\u56f4\u5185\u679a\u4e3e\u6ee1\u8db3\u8981\u6c42\u7684 mask\n        for mask in range(3**m):\n            color = list()\n            mm = mask\n            for i in range(m):\n                color.append(mm % 3)\n                mm //= 3\n            if any(color[i] == color[i + 1] for i in range(m - 1)):\n                continue\n            valid[mask] = color\n        \n        # \u9884\u5904\u7406\u6240\u6709\u7684 (mask1, mask2) \u4e8c\u5143\u7ec4\uff0c\u6ee1\u8db3 mask1 \u548c mask2 \u4f5c\u4e3a\u76f8\u90bb\u884c\u65f6\uff0c\u540c\u4e00\u5217\u4e0a\u4e24\u4e2a\u683c\u5b50\u7684\u989c\u8272\u4e0d\u540c\n        adjacent = defaultdict(list)\n        for mask1, color1 in valid.items():\n            for mask2, color2 in valid.items():\n                if not any(x == y for x, y in zip(color1, color2)):\n                    adjacent[mask1].append(mask2)\n        \n        f = [int(mask in valid) for mask in range(3**m)]\n        for i in range(1, n):\n            g = [0] * (3**m)\n            for mask2 in valid.keys():\n                for mask1 in adjacent[mask2]:\n                    g[mask2] += f[mask1]\n                    if g[mask2] >= mod:\n                        g[mask2] -= mod\n            f = g\n            \n        return sum(f) % mod\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.colorTheGrid(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
    "int",
    [["1\n1", "3"], ["1\n2", "6"], ["5\n5", "580986"]],
    ["dynamic-programming", "graph-coloring", "\u52a8\u6001\u89c4\u5212"],
    )
