    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    NEIGHBORS = [[1, 3], [0, 2, 4], [1, 5], [0, 4], [1, 3, 5], [2, 4]]\n\n    def slidingPuzzle(self, board: List[List[int]]) -> int:\n        # \u679a\u4e3e status \u901a\u8fc7\u4e00\u6b21\u4ea4\u6362\u64cd\u4f5c\u5f97\u5230\u7684\u72b6\u6001\n        def get(status: str) -> Generator[str, None, None]:\n            s = list(status)\n            x = s.index(\"0\")\n            for y in Solution.NEIGHBORS[x]:\n                s[x], s[y] = s[y], s[x]\n                yield \"\".join(s)\n                s[x], s[y] = s[y], s[x]\n\n        initial = \"\".join(str(num) for num in sum(board, []))\n        if initial == \"123450\":\n            return 0\n\n        q = deque([(initial, 0)])\n        seen = {initial}\n        while q:\n            status, step = q.popleft()\n            for next_status in get(status):\n                if next_status not in seen:\n                    if next_status == \"123450\":\n                        return step + 1\n                    q.append((next_status, step + 1))\n                    seen.add(next_status)\n        \n        return -1\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.slidingPuzzle(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
